import React from "react";
import { Container, Carousel, Button } from "react-bootstrap";

// Video carousel that opens videos in the shared VideoModal.
// Fill `videoList` with YouTube video IDs so we can open embeddable URLs.
const videoList = [
  // Replace these IDs with real video IDs from the channel. Example IDs used as placeholders.
  {
    id: "v1",
    title: "Live from Studio",
    vid: "dQw4w9WgXcQ",
    thumb: "/img/bg-img/bg-images-3-1200.jpg",
  },
  {
    id: "v2",
    title: "Official Music Video",
    vid: "9bZkp7q19f0",
    thumb: "/img/bg-img/bg-images-3-1200.jpg",
  },
];

export default function Video({ onWatchVideo }) {
  if (videoList.length === 0) return null;

  const handleOpen = (vid) => {
    // construct embed URL with autoplay
    const embed = `https://www.youtube.com/embed/${vid}?autoplay=1&rel=0`;
    if (onWatchVideo) onWatchVideo(embed, vid);
  };

  return (
    <section id="videos" className="video-area section-padding-100">
      <Container>
        <h3 className="mb-4">Videos</h3>
        <Carousel>
          {videoList.map((v) => (
            <Carousel.Item key={v.id}>
              <a
                href="#play"
                onClick={(e) => {
                  e.preventDefault();
                  handleOpen(v.vid);
                }}
              >
                <img
                  className="d-block w-100 rounded"
                  src={v.thumb}
                  alt={v.title}
                  style={{ maxHeight: 480, objectFit: "cover" }}
                />
              </a>
              <Carousel.Caption>
                <h5>{v.title}</h5>
                <p>
                  <Button
                    variant="light"
                    size="sm"
                    onClick={() => handleOpen(v.vid)}
                  >
                    Play
                  </Button>
                </p>
              </Carousel.Caption>
            </Carousel.Item>
          ))}
        </Carousel>
      </Container>
    </section>
  );
}
